import { db } from "@/lib/db";

export async function POST(request: Request) {
  const body = await request.json().catch(() => null);
  if (!body || typeof body.title !== "string" || body.title.trim() === "") {
    return Response.json({ error: "title is required" }, { status: 400 });
  }
  const seconds = Number(body.seconds);
  if (!Number.isInteger(seconds) || seconds < 2 || seconds > 5400) {
    return Response.json({ error: "seconds must be 2..5400" }, { status: 400 });
  }
  if (body.telescopeId) {
    const telescope = await db.telescope.findUnique({ where: { id: body.telescopeId } });
    if (!telescope) {
      return Response.json({ error: "telescope not found" }, { status: 404 });
    }
  }
  const duplicate = await db.exposure.findFirst({ where: { title: body.title.trim() } });
  if (duplicate) {
    return Response.json({ error: "title already exists" }, { status: 409 });
  }
  const exposure = await db.exposure.create({
    data: {
      title: body.title.trim(),
      seconds,
      ...(body.telescopeId ? { telescopeId: body.telescopeId } : {}),
      status: "queued",
    },
  });
  return Response.json(exposure, { status: 201 });
}

